class CExoLocString;  // fwd (hoist_headers)
class CSWSTrigger;  // fwd (hoist_headers)
class CSWSArea;

// A server-side trigger: the area-transition volume and the mine/trap volume.
class CSWSTrigger : public CSWSObject {
public:
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 57 slots
    virtual ~CSWSTrigger();  // slots 0-1 (D2+D0)
    virtual CSWSTrigger* AsSWSTrigger();
    virtual void AIUpdate();
    virtual void EventHandler(unsigned int nEventId, unsigned long long callerId, void* pData, unsigned int a, unsigned int b);
    virtual CExoLocString& GetFirstName();
    // </VTABLE-GEN>

    // The argument is the object id to seed the object with; every caller passes the assign-me-one
    // sentinel.
    CSWSTrigger(unsigned long long objectId);
    // Builds the trigger's polygon as a square of the given half-extent centred on the point.
    void CreateNewGeometry(float fHalfExtent, const Vector& vCentre, CSWSArea* pArea);
    void AddToArea(CSWSArea* pArea, float x, float y, float z, int a5);

    CExoString*    GetScriptName(int index);
    void*          GetClientTrigger();
#if KOTOR1  // K1 has no difficulty-scaled DC accessors: readers take the raw GFF int
    int            GetDisarmDC() { return m_baseDisarmDC; }
    int            GetDetectDC() { return m_baseDetectDC; }
#else
    int            GetDisarmDC();
    int            GetDetectDC();
#endif
    void           SetCreator(unsigned long long objectId);
    unsigned long long GetTargetArea();
    // Unregisters the trigger from its area, clears the area pointer and parks the trigger at the origin.
    void           RemoveFromArea();
    int            LoadFromTemplate(const CResRef& resRef);
    int            LineSegmentIntersectTrigger(const Vector& p1, const Vector& p2);
    int            InTrigger(const Vector& v);

    static float m_fTrapRadiusRange;
    // Caches the polygon's 2D bounding box and answers it through four out-params.
    void ComputeBoundingBox(float* pMinX, float* pMinY, float* pMaxX, float* pMaxY);
    // The centre of the 2D bounding box, dropped onto the area walkmesh.
    Vector GetFacingPosition();
    // Brute force: samples a lattice over the polygon's bounding box and keeps the sampled point that is
    // both inside the polygon and closest to the given point. Answers 0 when nothing sampled was inside.
    int            GetClosestPointWithinTrigger(const Vector& v, Vector* pOut);
    // Projects a world point onto the trigger geometry and writes the closest point on it.
    int            CalculateNearestPoint(const Vector& v, Vector* pOut);

    int  LoadTrigger(CResGFF* pGFF, CResStruct* pStruct);
    // Reads the geometry list; the stored points are relative to the trigger position and are translated
    // into world space here.
    void LoadTriggerGeometry(CResGFF* pGFF, CResList& list);
    void OnEnterMine(int nParam);
    // Whether this mine may fire at the given object at all: faction, mine immunity, and the party's
    // mine-safety feat.
    int  GetCanFireMineOnObject(unsigned long long oid, int nParam);
    int  SaveTrigger(CResGFF* pGFF, CResStruct* pStruct);

    CExoLocString m_localizedName;
    CExoString    m_linkedTo;
    CExoString    m_linkedToModule;
    unsigned char m_linkedToFlags;
    unsigned char _pad361[0x368 - 0x361];
    CExoString    m_scriptSlots[7];
    CExoString    m_keyName;
    int           m_nGeomVertCount;
    unsigned char _pad3ec[0x3f0 - 0x3ec];
    Vector*       m_pGeomVerts;
    int           m_nGeomVertCount2;
    unsigned char _pad3fc[0x400 - 0x3fc];
    Vector*       m_pGeomVerts2;
    int           m_nGeomIndexCount;
    int*          m_pGeomIndices;
    unsigned long long m_oidEnteringObject;
    unsigned long long m_oidExitingObject;
    unsigned long long m_oidDisarmedBy;
    CExoArrayList<unsigned long long> m_objectsInTrigger;

    int           m_bAreaTransition;
    unsigned int  m_nFaction;
    int           m_bTrap;
    int           m_bTrapDetectable;
    int           m_bTrapDisarmable;
    int           m_bMineFlagged;

    int           m_bAutoRemoveKey;
    int           m_bTrapOneShot;
    unsigned char m_trapType;
    unsigned char _pad461[0x464 - 0x461];
    int           m_baseDetectDC;
    int           m_baseDisarmDC;
#if !KOTOR1  // K1 has no OwnerDemolitionsSkill
    int           m_nOwnerDemolitionsSkill;
#endif
    float         m_fHighlightHeight;
#if !KOTOR1
    unsigned char _pad474[0x478 - 0x474];
#endif
    unsigned long long m_creatorId;
    float m_fBoundsMinX;
    float m_fBoundsMaxX;
    float m_fBoundsMinY;
    float m_fBoundsMaxY;
#if KOTOR1  // K1 keeps its own user-defined event number (K2 uses CSWSObject's)
    int           m_nUserDefinedEventNumber;
#endif
    unsigned char m_cursor;
    unsigned char _pad491[0x494 - 0x491];
    unsigned int  m_lastUpdateTod;
    unsigned int  m_lastUpdateDay;
    unsigned short m_loadScreenId;
    unsigned short m_nScanIndex;
    CExoLocString m_transitionDestination;
    int           m_bSetByPlayerParty;
};

